cat > /tmp/open.js <<'EOF'
(async () => {
  const c = window.canvas;
  await c.area('problem', { x: 0, y: 0, w: 900, h: 400, label: 'Problem', focus: true });
  await c.text('problem-ask', { x: 40, y: 70, w: 820, text:
`Qué pide la fuente (tu pedido)
• Que el sistema de preguntas aparezca en la card de la sesión del inicio del estudiante, como aparecen las encuestas.

Cómo está hoy, según los docs (estados-de-encuestas-y-sesiones.md, tiempo-real-del-aula.md)
• La card muestra el resumen, las encuestas activas (se vota o se deja feedback ahí mismo) y los links a Material, Encuestas y Preguntas, que abren un modal.
• Las preguntas se hacen, se votan y se borran en el aula; el profe las marca respondidas. Las respondidas no se ven para el estudiante.
• Una sesión anterior muestra sus preguntas solo para leer: ahí no se pregunta ni se vota.` });
  await c.text('problem-gaps', { x: 40, y: 380, w: 820, text:
`Lo que tu pedido todavía no dice
• "Similar a las encuestas": no dice qué parte de las preguntas va en la card (listarlas, hacer una nueva, votar) ni si reemplaza al link Preguntas.

Dónde las fuentes chocan con el pedido
• El inicio no recibe avisos: se actualiza cada cinco minutos o al recargar. En el aula las preguntas llegan al instante. Una pregunta nueva en la card tardaría hasta cinco minutos en aparecerles a los demás.` });
  await c.area('decisions', { x: 960, y: 0, w: 700, h: 300, label: 'Decisions' });
  await c.text('decisions-empty', { x: 1000, y: 70, w: 620, text: 'Todavía no hay decisiones.' });
  await c.note('n-open', { x: 960, y: 360, w: 700, text: 'Este canvas es la exploración de las preguntas en la card de la sesión. Hacé tu primera pregunta con un sticky note (o por voz) y apretá "Send to Agent".' });
  c.focus(null);
  return 'ok';
})()
EOF
agent-browser --session preguntas eval "$(cat /tmp/open.js)" 2>&1 | tail -3; agent-browser --session preguntas eval "editor.zoomToFit()" >/dev/null; agent-browser --session preguntas screenshot /tmp/preg-1.png | tail -1

