  await c.arrow('a-modal', 'ch-links', 'ch-modal', { text: 'abre' });
  await c.note('n-open', { text: 'Anoté las decisiones 3 y 4. Debajo explico la pregunta del modal con un esquema de la card destacada: el link Preguntas abriría lo mismo que ya está en la card.' });
