     4	
     5	// A filter by field: a value matches with `=`, an array with `in` and null with
     6	// `is null`; the fields combine with `and`.
     7	export type Where<A> = {
     8	  readonly [K in keyof A]?: A[K] | ReadonlyArray<A[K]> | null;
     9	};
    10	
    11	export interface Order<A> {
    12	  readonly field: keyof A & string;
    13	  readonly direction: "asc" | "desc";
    14	  readonly nulls?: "first" | "last";
    15	}
    16	
    17	// `orderBy` always ends with the id ascending, so the order is total. Without
    18	// `nulls`, nulls go first when ascending and last when descending, as in
    19	// SQLite. A page
    20	// holds at most `maxPage` rows, and `after` is the last row of the previous
    21	// page.
    22	export interface ListOptions<A> {
    23	  readonly where?: Where<A>;
    24	  readonly orderBy?: Order<A> | ReadonlyArray<Order<A>>;
    25	  readonly limit?: number;
    26	  readonly after?: A;
    27	}
    28	
    29	export interface UpsertOptions<Field extends string, Change> {
    30	  readonly target: ReadonlyArray<Field>;
    31	  readonly set?: Change;
    32	}
    33	
    34	// With `returning`, the rows are deleted, or marked as deleted, and given back
    35	// by the same statement.
    36	export interface RemoveOptions {
    37	  readonly returning: true;
    38	}
    39	
    40	export const maxPage = 100;
    41	
    42	// The operations every D1 store shares. A store's port takes the ones it
    43	// exposes and adds its own. An `upsert` without `set` leaves the row it
    44	// conflicts with as it was. A store with logical deletion leaves the deleted
    45	// rows out of every read, and its `remove` marks the row instead of deleting it.
    46	export interface Repository<A, New, Change> {
    47	  readonly get: (id: Ulid) => Effect.Effect<Option.Option<A>>;
    48	  readonly getMany: (ids: ReadonlyArray<Ulid>) => Effect.Effect<ReadonlyArray<A>>;
    49	  readonly find: (where: Where<A>) => Effect.Effect<Option.Option<A>>;
    50	  readonly list: (options?: ListOptions<A>) => Effect.Effect<ReadonlyArray<A>>;
    51	  readonly count: (where?: Where<A>) => Effect.Effect<number>;
    52	  readonly create: (row: New) => Effect.Effect<A>;
    53	  readonly createMany: (rows: ReadonlyArray<New>) => Effect.Effect<ReadonlyArray<A>>;
    54	  readonly update: (id: Ulid, change: Change) => Effect.Effect<Option.Option<A>>;
    55	  readonly updateWhere: (where: Where<A>, change: Change) => Effect.Effect<number>;
    56	  readonly upsert: (
    57	    row: New,
    58	    options: UpsertOptions<keyof New & string, Change>,
    59	  ) => Effect.Effect<void>;
    60	  readonly remove: (id: Ulid, options?: RemoveOptions) => Effect.Effect<Option.Option<A>>;
    61	  readonly removeWhere: {
    62	    (where: Where<A>): Effect.Effect<number>;
    63	    (where: Where<A>, options: RemoveOptions): Effect.Effect<ReadonlyArray<A>>;
    64	  };
    65	}

