const featuredIndex = (v) => v.sessions.findIndex((s) => s.featured);

const nodeOf = (v, i) => {
  const s = v.sessions[i];

  if (s.featured) {
    return `<div class="node live">${i + 1}</div>`;
  }

  if (!s.enabled) {
    return `<div class="node lock">${i + 1}</div>`;
  }

  const featured = featuredIndex(v);

  return featured === -1 || i > featured ? '<div class="node later"></div>' : '<div class="node done">✓</div>';
