      : `<div class="card closed ${s.enabled ? '' : 'locked'}" style="${s.enabled ? `background:${color(i + 1)}` : ''}">
          <div class="head" data-toggle="${i}"><span class="grip" title="Arrastrar para reordenar">${ic('grip-vertical', 18)}</span><h3>${s.title}</h3>${s.featured ? featChip(true) : ''}${stateTag(s)}</div>
