  const c = window.canvas
  const editor = window.editor
  const wait = (ms) => new Promise((r) => setTimeout(r, ms))

  const place = async (item, x, y, into) => {
    if (item.type === 'mermaid') {
      await c.mermaid(item.name, { x, y, source: item.source }, 0)
      await wait(1200)
      await c.fit(item.name)
      if (item.w != null) {
        const b = c.bounds(item.name)
        await c.resize(item.name, { w: item.w, h: (b.h * item.w) / b.w })
      }
    } else if (item.type === 'mock') {
      await c.mock(item.name, { x, y, w: item.w, kind: item.kind, data: item.data, into }, 0)
    } else if (item.type === 'text') {
      await c.text(item.name, { x, y, w: item.w, text: item.text, mono: item.mono ?? false, into }, 0)
    } else if (item.type === 'card') {
      const opts = { x, y, w: item.w, text: item.text, into }
      if (item.color != null) opts.color = item.color
      if (item.fill != null) opts.fill = item.fill
      if (item.mono != null) opts.mono = item.mono
      await c.card(item.name, opts, 0)
    } else if (item.type === 'note') {
      await c.note(item.name, { x, y, w: item.w, text: item.text }, 0)
    }
  }

  // One part: an area holding rows of items; the items of a row sit side by side at their dx.
  const part = async (name, { x, y, w, label }, rows) => {
    await c.area(name, { x, y, w, h: 200, label }, 0)
    let top = y + 80

    for (const row of rows) {
      let rowBottom = top

      for (const item of row) {
        await place(item, x + (item.dx ?? 40), top + (item.dy ?? 0), name)
        const b = c.bounds(item.name)
        rowBottom = Math.max(rowBottom, b.y + b.h)
      }

      top = rowBottom + 50
    }

    await c.resize(name, { h: top - y })
    return c.bounds(name)
  }

  // A note joined to one card inside a component-cards mock, at the card title's left or right edge.
  const pointArrow = async (name, from, mock, card, side) => {
    const shapeId = c.id(mock)
    editor.zoomToBounds(editor.getShapePageBounds(shapeId), { inset: 40 })
    await wait(600)
    const el = document.querySelector(`[data-shape-id="${shapeId}"] [data-card="${card}"]`)
    const b = editor.getShapePageBounds(shapeId)
    if (el == null) return false
    const r = el.getBoundingClientRect()
    const p = editor.screenToPage({ x: side === 'left' ? r.left + 2 : r.right - 2, y: r.top + 14 })
    const anchor = { x: (p.x - b.x) / b.w, y: (p.y - b.y) / b.h }
    const arrowId = c.id(name)
    editor.createShape({ id: arrowId, type: 'arrow', x: 0, y: 0, props: { start: { x: 0, y: 0 }, end: { x: 1, y: 1 }, size: 's', color: 'black' } })
    editor.createBindings([
      { type: 'arrow', fromId: arrowId, toId: c.id(from), props: { terminal: 'start', normalizedAnchor: { x: side === 'left' ? 1 : 0, y: 0.5 }, isPrecise: true, isExact: false } },
      { type: 'arrow', fromId: arrowId, toId: shapeId, props: { terminal: 'end', normalizedAnchor: anchor, isPrecise: true, isExact: true } },
    ])
    return true
  }

  window.pd = { wait, place, part, pointArrow }
})()
