(async () => {
  const S = window.__spec
  const c = window.canvas
  const pd = window.pd
  const W = 1600
  const GAP = 160
  const TOP = 1500
  const colX = (n) => 40 + (n - 1) * (W + GAP)

  await c.text('tree', { x: 40, y: 40, w: 2200, text: S.tree, mono: true }, 0)

  const label = (n, part, status) => `kurasu · ${S.branches[n - 1][1]} · ${part} · ${status}`

  let y = {}
  const next = async (n, name, part, status, rows) => {
    const b = await pd.part(name, { x: colX(n), y: y[n] ?? TOP, w: W, label: label(n, part, status) }, rows)
    y[n] = b.y + b.h + 60
  }

  const iface = (n) => S.iface[n].map((it, i) => ({ type: 'mock', name: `if${n}-${i}`, kind: it.kind, data: it.data, w: 480, dx: 40 + (i % 3) * 520, dy: Math.floor(i / 3) * 0 }))
  const ifaceRows = (n) => {
    const all = iface(n)
    const rows = []
    for (let i = 0; i < all.length; i += 3) rows.push(all.slice(i, i + 3))
    return rows
  }
  const files = (n) => [[{ type: 'mock', name: `ft${n}`, kind: 'file-tree', data: { lines: S.files[n] }, w: 1100 }]]

  // 1
  await next(1, 'p1-1', '1.1 Class diagram', 'settled', [[{ type: 'mermaid', name: 'mm-class', source: S.mmd.class, w: 1100 }],
    [{ type: 'text', name: 't1-1', w: 1500, text: 'El índice copia la forma de codes_current_enrollment_unique. drizzle-kit genera 0004_featured_session con dos ADD COLUMN y el índice; SQLite no reconstruye la tabla. questions-opened no necesita migración: la columna type es text sin CHECK.' }]])
  await next(1, 'p1-2', '1.2 Interfaces y module list', 'settled', [...ifaceRows(1), ...files(1)])

  // 2
  await next(2, 'p2-1', '2.1 Callstack', 'settled', [[{ type: 'mermaid', name: 'mm-patch', source: S.mmd.patch, w: 900 }],
    [{ type: 'text', name: 't2-1', w: 1500, text: 'Las cuatro acciones (destacar, sacar la marca, habilitar destacando, deshabilitar la destacada) y el switch de preguntas destacadas son este PATCH. Cuando una sesión deja de ser la destacada, lo que pierde se escribe en un batch con el cambio pedido; después salen las novedades y se avisa a su aula.' }]])
  await next(2, 'p2-2', '2.2 El batch', 'open', [[{ type: 'mermaid', name: 'mm-batch', source: S.mmd.batch, w: 560 }, { type: 'card', name: 'q2', text: S.q2, w: 900, dx: 660 }],
    [{ type: 'text', name: 't2-2', w: 1500, text: 'Desmarca antes de marcar: el índice nunca ve dos destacadas. B2 cierra solo los ids leídos antes. Si una sentencia falla, D1 no aplica ninguna y el pedido responde 500.' }]])
  await next(2, 'p2-3', '2.3 Interfaces y module list', 'settled', [...ifaceRows(2), ...files(2)])

  // 3
  await next(3, 'p3-1', '3.1 Callstack', 'settled', [[{ type: 'card', name: 'cs3', text: S.call3, w: 1500, mono: true, color: 'grey' }]])
  await next(3, 'p3-2', '3.2 La regla', 'open', [[{ type: 'mermaid', name: 'mm-rule', source: S.mmd.rule, w: 640 }, { type: 'card', name: 'q1', text: S.q1, w: 800, dx: 740 }]])
  await next(3, 'p3-3', '3.3 Interfaces y module list', 'settled', [...ifaceRows(3), ...files(3)])

  // screens 4-7
  for (const n of [4, 5, 6, 7]) {
    const shots = S.screens[n]
    const rows = []
    for (let i = 0; i < shots.length; i += 2) {
      rows.push(shots.slice(i, i + 2).flatMap(([kind, state, cap], k) => [
        { type: 'text', name: `cap${n}-${i + k}`, text: cap, w: 700, dx: 40 + k * 780 },
      ]))
      rows.push(shots.slice(i, i + 2).map(([kind, state], k) => ({ type: 'mock', name: `scr${n}-${i + k}`, kind, data: { state }, w: 720, dx: 40 + k * 780 })))
    }
    rows.push([{ type: 'text', name: `sn${n}`, w: 1500, text: S.screenNotes[n] }])
    await next(n, `p${n}-1`, `${n}.1 Screen layout`, 'settled', rows)
    await next(n, `p${n}-2`, `${n}.2 Component tree`, 'settled', [[{ type: 'mock', name: `ct${n}`, kind: 'component-cards', data: S.comp[n], w: 900, dx: 350 }]])
    if (S.state[n] != null) {
      const st = S.state[n]
      const rows2 = []
      for (let i = 0; i < st.length; i += 2) {
        rows2.push(st.slice(i, i + 2).map((it, k) => ({ type: 'mock', name: `st${n}-${i + k}`, kind: it.kind, data: it.data, w: 740, dx: 40 + k * 780 })))
      }
      await next(n, `p${n}-3`, `${n}.3 State`, 'settled', rows2)
    }
    await next(n, `p${n}-4`, `${n}.${S.state[n] != null ? 4 : 3} Interfaces y module list`, 'settled', [...ifaceRows(n), ...files(n)])
  }

  // 8
  await next(8, 'p8-1', '8.1 Standards', 'settled', [[{ type: 'mermaid', name: 'mm-std', source: S.mmd.std, w: 1500 }]])

  await c.note('n-agent', { x: 2400, y: 40, w: 1000, text: 'Fast track: todo dibujado de una vez. Quedan dos preguntas abiertas, Q1 en la rama 3 y Q2 en la rama 2. Lo demás sale del design, las notas, los prototipos y el código en c4cf12a, con su fuente en cada hoja. Respondé con stickies o por voz.' })
  c.focus(null)
  return 'done'
})()

