type Kind = 'done' | 'live' | 'later'

const Node = ({ kind, n }: { kind: Kind; n: number }) => (
  <div
    style={{
      width: 38,
      height: 38,
      borderRadius: '50%',
      display: 'grid',
      placeItems: 'center',
      fontWeight: 700,
      fontSize: 16,
      flex: 'none',
      background: kind === 'done' ? INK : kind === 'live' ? LIVE : LINE,
      color: PAPER,
      boxShadow: kind === 'live' ? `0 0 0 5px ${LIVE}40` : undefined,
    }}
  >
    {kind === 'done' ? '✓' : kind === 'live' ? n : ''}
  </div>
)

const Path = ({ kinds }: { kinds: Kind[] }) => (
  <div style={{ display: 'grid', gridTemplateColumns: '38px 1fr', columnGap: 14, marginTop: 10 }}>
    {kinds.map((kind, index) => (
      <div key={index} style={{ display: 'contents' }}>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <Node kind={kind} n={index + 1} />
          {index < kinds.length - 1 ? <div style={{ width: 4, flex: 1, minHeight: 12, background: LINE, borderRadius: 2 }} /> : null}
        </div>
        <div style={{ paddingBottom: 10 }}>
          <div style={{ background: CARD[index % 4], borderRadius: 16, padding: '8px 14px', fontSize: 15, fontWeight: 700 }}>{SESSIONS[index]}</div>
        </div>
      </div>
    ))}
  </div>
)

const Screen = ({ state }: Props) => {
  const featured = state !== 'sin-destacada'

  return (
    <div data-root style={{ alignSelf: 'flex-start', fontFamily: HAND, color: INK, background: WINDOW, borderRadius: 16, padding: '24px 32px 30px' }}>
      <div style={{ display: 'flex', alignItems: 'center' }}>
        <span style={{ flex: 1, fontSize: 26, fontWeight: 700 }}>Hola, Lucía</span>
        <span style={{ width: 40, height: 40, borderRadius: '50%', background: CARD[2], display: 'grid', placeItems: 'center', fontSize: 20 }}>🦊</span>
      </div>
      {featured ? <Hero state={state} /> : null}
      <div style={{ fontSize: 17, fontWeight: 700, marginTop: 24 }}>{featured ? 'Otras sesiones' : 'Sesiones'}</div>
      <Path kinds={featured ? ['done', 'live', 'later'] : ['later', 'later', 'later']} />
    </div>
  )

import type { UseMutationOptions, UseQueryOptions } from "@tanstack/react-query";
import type * as Effect from "effect/Effect";

import type { KurasuClient } from "./run-api.ts";

// What an endpoint of the contract can fail with, as the HttpApi client types
// it: the endpoint's own errors, its middleware's, the network and a response
// that does not decode.
export type EndpointError<
  G extends keyof KurasuClient,
  N extends keyof KurasuClient[G],
> = KurasuClient[G][N] extends (...args: never) => Effect.Effect<unknown, infer E> ? E : never;

export type QueryOptions<A, E> = Omit<UseQueryOptions<A, E>, "queryKey" | "queryFn">;

export type MutationOptions<A, I, E> = Omit<UseMutationOptions<A, E, I>, "mutationFn">;
import type { QueryKey } from "@tanstack/react-query";
import { useQuery } from "@tanstack/react-query";
import type * as Effect from "effect/Effect";

import type { QueryOptions } from "./api-error.ts";
import { runApi } from "./run-api.ts";
import type { KurasuClient } from "./run-api.ts";

export interface ApiQuery<A, E> {
  readonly queryKey: QueryKey;
  readonly call: (api: KurasuClient) => Effect.Effect<A, E>;
  readonly options?: QueryOptions<A, E> | undefined;
}

export const useApiQuery = <A, E>({ queryKey, call, options }: ApiQuery<A, E>) =>
  useQuery({
    queryKey,
    queryFn: () => runApi(call),
    ...options,
  });

