  const delPrefix = (re) => ed.deleteShapes(ed.getCurrentPageShapes().filter((s) => re.test(s.id.replace('shape:', ''))).map((s) => s.id))
  let tag = Date.now() % 100000

  // close Q3 in 4.1 and refresh the screen mocks (mockups changed on disk, the shapes redraw themselves)
