  await c.area('p4-1', { label: 'kurasu · 4 Inicio del estudiante · 4.1 Screen layout · settled' })
  await c.text('sn4', { text: S.notes[4] })
  await c.text('sn6', { text: S.notes[6] })

  const redo = async (n, area, build) => {
    delPrefix(new RegExp(`^(ct|st|if|ft)${n}[-b]?`))
    for (const s of ed.getCurrentPageShapes()) if (s.type === 'arrow' && ed.getBindingsFromShape(s.id, 'arrow').length < 2) ed.deleteShape(s.id)
    await c.focus(area)
