    await redo(n, ct, async (b) => { await c.mock(`ct${n}x${tag}`, { x: b.x + 350, y: b.y + 80, w: 900, kind: 'component-cards', data: S.comp[n], into: ct }, 0) })
    if (S.state[n] != null) {
      const st = `p${n}-3`
      const b = c.bounds(st)
      let y = b.y + 80, rowH = 0
      for (let i = 0; i < S.state[n].length; i++) {
        const it = S.state[n][i], col = i % 2
        if (col === 0 && i > 0) { y += rowH + 40; rowH = 0 }
        await c.mock(`st${n}x${tag}-${i}`, { x: b.x + 40 + col * 780, y, w: 740, kind: it.kind, data: it.data, into: st }, 0)
        rowH = Math.max(rowH, c.bounds(`st${n}x${tag}-${i}`).h)
      }
      await c.fit(st)
    }
    const ia = `p${n}-4`
    const b = c.bounds(ia)
    let x = b.x + 40, y = b.y + 80, rowH = 0
    for (let i = 0; i < S.iface[n].length; i++) {
      if (i > 0 && i % 3 === 0) { x = b.x + 40; y += rowH + 40; rowH = 0 }
      await c.mock(`if${n}x${tag}-${i}`, { x, y, w: 480, kind: 'interface-card', data: S.iface[n][i].data, into: ia }, 0)
      rowH = Math.max(rowH, c.bounds(`if${n}x${tag}-${i}`).h); x += 520
    }
    await c.mock(`ft${n}x${tag}`, { x: b.x + 40, y: y + rowH + 50, w: 1100, kind: 'file-tree', data: { lines: S.files[n] }, into: ia }, 0)
    await c.fit(ia)
  }
  c.focus(null)
  return 'ok'
})()
