(async () => {
  const c = window.canvas, ed = window.editor
  const t = c.bounds('tree')
  const top = Math.min(...ed.getCurrentPageShapes().filter((s) => /^p\d-1$/.test(s.id.replace('shape:', ''))).map((s) => ed.getShapePageBounds(s.id).y))
  const dy = t.y + t.h + 120 - top
  if (dy <= 0) return 'no shift'
  const ids = ed.getCurrentPageShapes().filter((s) => s.parentId === ed.getCurrentPageId() && !['tree', 'n-agent'].includes(s.id.replace('shape:', '')) && ed.getShapePageBounds(s.id).y >= top - 10 && s.type !== 'arrow').map((s) => s.id)
  ed.run(() => { for (const id of ids) { const s = ed.getShape(id); ed.updateShape({ id, type: s.type, y: s.y + dy }) } })
  return 'shifted ' + dy + ' ' + ids.length
})()
EOF
