import type { Session } from "@kurasu/contract/sessions";
import type { Position } from "@kurasu/slides/messages";
import { useQueryClient } from "@tanstack/react-query";

import type { EndpointError, MutationOptions } from "../../api/api-error.ts";
import { queryKeys } from "../../api/query-keys.ts";
import { useApiMutation } from "../../api/useApiMutation.ts";

export interface SlideMove {
  readonly id: string;
  readonly position: Position;
}

// No optimistic patch: the teacher's screen shows its own position while its
// moves save. A saved move cancels a refetch still on the way, because the
// refetch could carry an older position than the one just saved.
export const useMoveSlide = (
  options?: MutationOptions<Session, SlideMove, EndpointError<"adminSessions", "update">>,
) => {
  const queryClient = useQueryClient();

  return useApiMutation({
    call: (api, input) =>
      api.adminSessions.update({
        params: { id: input.id },
        payload: { currentSlide: input.position.slide, currentStep: input.position.step },
      }),
    errorToast: () => "No se pudo mover la slide.",
    onSuccess: async (session, input) => {
      await queryClient.cancelQueries({
        queryKey: queryKeys.adminSession(input.id),
        exact: true,
      });
      queryClient.setQueryData(queryKeys.adminSession(input.id), session);
    },
    onError: () =>
      queryClient.invalidateQueries({ queryKey: queryKeys.adminSession(""), exact: false }),
    options,
  });
};

import type { Session } from "@kurasu/contract/sessions";
import type { Position } from "@kurasu/slides/messages";
import { samePosition } from "@kurasu/slides/navigation";
import { useRef, useState } from "react";

import { useMoveSlide } from "../sessions/useMoveSlide.ts";

// While moves save, the screen shows its own position and ignores what the
// server answers, because those answers arrive late and would send it back.
// Moves save one at a time, and a move made while another saves only keeps
// the last position.
export const useSlideMoves = (session: Session) => {
  const move = useMoveSlide();

  const [moving, setMoving] = useState<Position | null>(null);
  const isSaving = useRef(false);
  const waiting = useRef<Position | null>(null);

  const finish = () => {
    waiting.current = null;
    isSaving.current = false;
    setMoving(null);
  };

  const save = (position: Position) => {
    isSaving.current = true;

    move.mutateAsync({ id: session.id, position }).then(() => {
      const next = waiting.current;

      waiting.current = null;

      if (next != null && !samePosition(next, position)) {
        save(next);

        return;
      }

      finish();
    }, finish);
  };

  const navigate = (position: Position) => {
    setMoving(position);

    if (isSaving.current) {
      waiting.current = position;

      return;
    }

    save(position);
  };

  return {
    position: moving ?? { slide: session.currentSlide, step: session.currentStep },
    navigate,
  };
};

import type { Session } from "@kurasu/contract/sessions";

import { useAdminMaterials } from "../materials/useAdminMaterials.ts";
import { useSlidesMaterial } from "../materials/useSlidesMaterial.ts";
import { PresentButton } from "./PresentButton.tsx";
import { SlideStage } from "./SlideStage.tsx";
import { SlideStageSkeleton } from "./SlideStageSkeleton.tsx";
import { useSlideMoves } from "./useSlideMoves.ts";

interface Props {
  session: Session;
}

// The teacher drives the session's position: each move is saved, and the
// classroom tells the students.
export const TeacherSlides = ({ session }: Props) => {
  const materials = useAdminMaterials(session.id);
  const slides = useSlidesMaterial(materials.data);
  const moves = useSlideMoves(session);

  const controls = <PresentButton sessionId={session.id} />;

  return materials.data == null || (slides != null && slides.html == null) ? (
    <SlideStageSkeleton controls={controls} />
  ) : (
    <SlideStage
      html={slides?.html ?? null}
      position={moves.position}
      onNavigate={moves.navigate}
      controls={controls}
    />
  );
};

